tools.flatten:
def flatten(nested):
    """Recursively flatten a nested list of integers.

    Args:
        nested (list): A list which may contain integers or other lists.

    Returns:
        list: A flat list containing all the integers from the nested structure.
    """
    result = []
    def _flatten(item):
        if isinstance(item, list):
            for sub in item:
                _flatten(sub)
        else:
            result.append(item)
    _flatten(nested)
    return result

